    body: {
      profiles: [handle],
      resultsPerPage: Number(cfg('TIKTOK_VIDEOS', '3')),
      profileSorting: 'latest',
      commentsPerPost: Number(cfg('TIKTOK_COMMENTS_PER_VIDEO', '30')),
      maxRepliesPerComment: 0,
    },
    timeout: 300000,
  });
